using System.Diagnostics;
using System.Text.Json;
namespace DiskLens;
public static class Benchmark {
 sealed class Progress(Action<string> action):IProgress<string>{public void Report(string value)=>action(value);}
 public static async Task<int> Run(string[] args){try{var root=System.IO.Path.GetFullPath(args[1]);var output=System.IO.Path.GetFullPath(args[2]);Directory.CreateDirectory(root);const int folders=300,perFolder=100;if(!File.Exists(System.IO.Path.Combine(root,"fixture-complete"))){for(int folder=0;folder<folders;folder++){var dir=System.IO.Path.Combine(root,"group-"+folder/30,"folder-"+folder);Directory.CreateDirectory(dir);for(int file=0;file<perFolder;file++)File.WriteAllText(System.IO.Path.Combine(dir,$"file-{file:D3}-{(file%17==0?"report":"data")}.{(file%17==0?"pdf":"bin")}"),"0123456789");}File.WriteAllText(System.IO.Path.Combine(root,"fixture-complete"),"fixture");}
 var home=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(output)!,"benchmark-index-"+Guid.NewGuid().ToString("N"));var store=new Store(home);var measurements=new List<object>();
 for(int pass=0;pass<3;pass++){var clock=Stopwatch.StartNew();double traversal=0;var progress=new Progress(text=>{if(text.StartsWith("Finalizing")&&traversal==0)traversal=clock.Elapsed.TotalMilliseconds;});var pending=System.IO.Path.Combine(home,Guid.NewGuid().ToString("N")+".pending");var scan=await new Scanner().Run(root,pending,false,"",progress,CancellationToken.None);store.Commit(scan,pending,20);clock.Stop();if(scan.Files!=folders*perFolder+1||scan.Bytes!=folders*perFolder*10+7||scan.Issues!=0)throw new Exception("Benchmark totals mismatch");var queries=new List<object>();foreach(var query in new[]{"","*report*.pdf","does-not-exist-xyz"}){var timer=Stopwatch.StartNew();var rows=store.Search(scan,query,0,0,"All files");timer.Stop();queries.Add(new{Query=query,Milliseconds=timer.Elapsed.TotalMilliseconds,Rows=rows.Count});}measurements.Add(new{Pass=pass+1,Files=scan.Files,Bytes=scan.Bytes,TraversalMilliseconds=traversal,TotalMilliseconds=clock.Elapsed.TotalMilliseconds,IndexBytes=new FileInfo(store.PathFor(scan)).Length,ParentPeakWorkingSetBytes=Process.GetCurrentProcess().PeakWorkingSet64,Queries=queries});}
 Directory.CreateDirectory(System.IO.Path.GetDirectoryName(output)!);File.WriteAllText(output,JsonSerializer.Serialize(new{Version=typeof(Scanner).Assembly.GetName().Version!.ToString(),Fixture=root,Description="30,001 physical files, 311 folders; repeated warm-cache scans; complete WPF scanner plus snapshot publication. Parent working set excludes filesystem worker. Not a whole-drive benchmark.",Measurements=measurements},new JsonSerializerOptions{WriteIndented=true}));return 0;}catch(Exception e){File.WriteAllText(args[2]+".error.txt",e.ToString());return 1;}}
}
